// Drives freeze_frame through the real FFI on the clips a person can select.
use framejob_core::ffi::{rc_project_from_json, rc_project_to_json};
use framejob_core::ffi_edit::rc_project_apply;
use framejob_core::model::Project;
use std::ffi::{c_char, CStr, CString};
use std::ptr;

fn text(p: *mut c_char) -> Option<String> {
    if p.is_null() {
        None
    } else {
        Some(unsafe { CStr::from_ptr(p) }.to_string_lossy().into_owned())
    }
}

fn apply(p: *const Project, op: &str) -> (*mut Project, Option<String>, Option<String>) {
    let c = CString::new(op).unwrap();
    let mut err: *mut c_char = ptr::null_mut();
    let mut why: *mut c_char = ptr::null_mut();
    let next = unsafe { rc_project_apply(p, c.as_ptr(), &mut err, &mut why) };
    (next, text(err), text(why))
}

fn main() {
    let json = r#"{
  "version": 1,
  "canvas": {"width": 1920, "height": 1080, "fps": [30, 1], "background": [0, 0, 0, 1],
             "fit_new_clips": true, "timecode_frames": true},
  "media": [
    {"id": 1, "path": "/m/talk.mov", "kind": "video", "duration": 36000000,
     "width": 1920, "height": 1080, "fps": [30, 1], "has_video": true, "has_audio": true},
    {"id": 2, "path": "/m/song.wav", "kind": "audio", "duration": 36000000,
     "has_video": false, "has_audio": true},
    {"id": 3, "path": "/m/pic.png", "kind": "image", "duration": 0,
     "width": 100, "height": 100, "has_video": false, "has_audio": false}
  ],
  "tracks": [{"id": 4, "name": "A"}, {"id": 5, "name": "B"}, {"id": 6, "name": "C"},
             {"id": 7, "name": "D"}],
  "clips": [
    {"id": 10, "track": 4, "start": 0, "duration": 12000000,
     "source": {"kind": "media", "media": 1, "in": 0}, "video": {}, "audio": {}},
    {"id": 20, "track": 5, "start": 0, "duration": 12000000,
     "source": {"kind": "media", "media": 2, "in": 0}, "audio": {}},
    {"id": 30, "track": 6, "start": 0, "duration": 12000000,
     "source": {"kind": "text"}, "video": {}, "text": {"content": "Hello"}},
    {"id": 40, "track": 7, "start": 0, "duration": 12000000,
     "source": {"kind": "image", "media": 3}, "video": {}}
  ],
  "markers": [],
  "nests": [],
  "next_id": 100
}"#;
    let c = CString::new(json).unwrap();
    let mut err: *mut c_char = ptr::null_mut();
    let p = unsafe { rc_project_from_json(c.as_ptr(), &mut err) };
    if p.is_null() {
        println!("load failed: {:?}", text(err));
        return;
    }
    for id in [20, 30, 40] {
        let (next, e, w) = apply(
            p,
            &format!(r#"{{"op":"freeze_frame","clip":{id},"at":3000000}}"#),
        );
        println!("clip {id}: applied={} err={e:?} refused={w:?}", !next.is_null());
    }

    // The sound half of a detached video clip.
    let (d, e, w) = apply(p, r#"{"op":"detach_audio","clip":10}"#);
    println!("detach: applied={} err={e:?} refused={w:?}", !d.is_null());
    if d.is_null() {
        return;
    }
    let doc: serde_json::Value =
        serde_json::from_str(&text(unsafe { rc_project_to_json(d) }).unwrap()).unwrap();
    let half = doc["clips"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["linked"] == 10)
        .unwrap();
    let id = half["id"].as_u64().unwrap();
    println!(
        "sound half: id={id} track={} enabled={} has_video_group={}",
        half["track"],
        half["enabled"],
        !half["video"].is_null()
    );
    let (f, e, w) = apply(
        d,
        &format!(r#"{{"op":"freeze_frame","clip":{id},"at":3000000}}"#),
    );
    println!("freeze sound half: applied={} err={e:?} refused={w:?}", !f.is_null());
    if !f.is_null() {
        let doc: serde_json::Value =
            serde_json::from_str(&text(unsafe { rc_project_to_json(f) }).unwrap()).unwrap();
        for c in doc["clips"].as_array().unwrap() {
            if c["source"]["kind"] == "still" {
                println!(
                    "still: id={} track={} start={} enabled={} source={}",
                    c["id"], c["track"], c["start"], c["enabled"], c["source"]
                );
            }
        }
    }
    // A picture switched off with set_enabled.
    let (o, e, w) = apply(p, r#"{"op":"set_enabled","clip":10,"video":false}"#);
    println!("switch picture off: applied={} err={e:?} refused={w:?}", !o.is_null());
    if !o.is_null() {
        let (f, e, w) = apply(o, r#"{"op":"freeze_frame","clip":10,"at":3000000}"#);
        println!("freeze picture-off clip: applied={} err={e:?} refused={w:?}", !f.is_null());
    }
}
